#!/usr/bin/env python3
from pwn import *
import time

# Set up logging
context.log_level = 'debug'

def test_size(size):
    try:
        # Connect to the service
        conn = remote('pwn.chal.csaw.io', 8000)

        # Generate cyclic pattern of specified size
        pattern = cyclic(size)

        # Send the pattern
        conn.send(pattern)

        # Try to receive any response
        try:
            response = conn.recvall(timeout=1)
            return (True, response)
        except:
            return (True, None)
        finally:
            conn.close()
    except Exception as e:
        return (False, str(e))

# Test different sizes
for size in range(200, 1001, 64):
    print(f"\n[+] Testing size: {size}")
    success, result = test_size(size)

    if success:
        if result:
            print(f"[+] Got response: {hexdump(result)}")
        else:
            print("[-] No response received")
    else:
        print(f"[-] Connection failed: {result}")

    # Add small delay between attempts
    time.sleep(1)

